/* Six contextual self-promotions: subtle dots, feathered artwork, no numeric tabs. */
.tcScreenreaderOnly{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;
 margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.tcStitchShell .tcInlineHousePromo,.tcStitchShell .tcHouseAd.tcPremiumAd{
 background:linear-gradient(120deg,#0a382b,#1b5d41)!important;border:0!important;
 border-radius:16px!important;box-shadow:0 7px 19px #123e2920!important;
 overflow:hidden!important;isolation:isolate!important;position:relative!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseIcon,
.tcStitchShell .tcInlineHousePromo .tcInlineHouseIcon:has(.tcHouseFallbackThumb){
 border:0!important;border-radius:0!important;box-shadow:none!important;background:#255943!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseIcon .tcHouseFallbackThumb,
.tcStitchShell .tcInlineHousePromo .tcInlineHouseIcon .tcAdImage{border-radius:0!important;object-fit:cover!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseIcon:has(.tcHouseFallbackThumb)::after{
 content:'';position:absolute;inset:0;z-index:3;pointer-events:none;
 background:linear-gradient(90deg,#14513cf0 0%,#14513c70 20%,transparent 80%)!important}
.tcStitchShell .tcInlineHousePromo .tcInlineGalleryControls{
 position:absolute!important;z-index:8!important;bottom:7px!important;right:6px!important;
 left:auto!important;transform:none!important;max-width:none!important;
 display:flex!important;flex-flow:row nowrap!important;gap:1px!important;padding:2px!important;
 background:#06372bbf!important;border-radius:30px!important}
.tcStitchShell .tcInlineHousePromo .tcInlineGalleryControls button,
.tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryControls button{
 display:grid!important;place-items:center!important;position:relative!important;
 flex:0 0 19px!important;width:19px!important;min-width:19px!important;max-width:19px!important;
 height:23px!important;min-height:23px!important;max-height:23px!important;padding:0!important;
 margin:0!important;border:0!important;border-radius:20px!important;
 background:transparent!important;color:transparent!important;font-size:0!important;line-height:0!important;
 box-shadow:none!important}
.tcStitchShell .tcInlineHousePromo .tcInlineGalleryControls button::after,
.tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryControls button::after{
 content:'';display:block!important;width:6px!important;height:6px!important;border-radius:15px!important;
 background:#f1f9ebbe!important;transition:width .15s ease!important}
.tcStitchShell .tcInlineHousePromo .tcInlineGalleryControls button[aria-pressed=true]::after,
.tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryControls button[aria-pressed=true]::after{
 width:14px!important;background:#d9f59d!important}
.tcStitchShell .tcInlineHousePromo .tcInlineGalleryControls button:focus-visible,
.tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryControls button:focus-visible{
 outline:2px solid #e0f5a3!important;outline-offset:2px!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy{position:relative!important;z-index:5!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy small{color:#d9f4b9!important}
.tcStitchShell .tcInlineHousePromo>button{
 background:#dff3ab!important;color:#194d34!important;border:0!important;border-radius:12px!important;
 box-shadow:none!important;position:relative!important;z-index:6!important;min-height:40px!important}
.tcStitchShell .tcHouseAd.tcPremiumAd .tcCampaignVisual{border-radius:0!important;border:0!important}
.tcStitchShell .tcHouseAd.tcPremiumAd .tcCampaignVisual::after{
 content:'';position:absolute;inset:0;z-index:4;pointer-events:none;
 background:linear-gradient(90deg,#1b5844a8,#1b58444d 30%,transparent 72%)!important}
.tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryControls{
 position:absolute!important;bottom:8px!important;right:7px!important;z-index:8!important;
 flex-flow:row nowrap!important;gap:1px!important;border-radius:30px!important;
 background:#06372bbf!important;padding:2px!important;max-width:none!important}
.tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryLabel{display:none!important}
.tcStitchShell .tcHouseAd.tcPremiumAd .tcCampaignCopy>button{
 background:#dff3ab!important;color:#194d34!important;border:0!important;border-radius:12px!important}
@media(max-width:767px){
 .tcStitchShell .tcInlineHousePromo:has(.tcHouseFallbackThumb),
 .tcStitchShell .tcInlineHousePromo[data-placement=search]:has(.tcHouseFallbackThumb),
 .tcStitchShell .tcInlineHousePromo[data-placement=listing]:has(.tcHouseFallbackThumb){
  display:grid!important;grid-template-columns:minmax(0,1.1fr) minmax(120px,.9fr)!important;
  grid-template-rows:minmax(0,1fr) auto!important;grid-template-areas:"copy photo" "cta photo"!important;
  gap:5px!important;min-height:168px!important;max-height:none!important;
  width:calc(100% - 24px)!important;max-width:100%!important;margin:8px auto!important;padding:12px!important}
 .tcStitchShell .tcInlineHousePromo[data-placement=listing]:has(.tcHouseFallbackThumb){width:100%!important;margin:7px 0!important}
 .tcStitchShell .tcInlineHousePromo .tcInlineHouseIcon:has(.tcHouseFallbackThumb){
  grid-area:photo!important;grid-column:2!important;grid-row:1/3!important;
  align-self:stretch!important;width:100%!important;height:100%!important;
  min-height:100%!important;max-height:none!important;border-radius:0!important}
 .tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy{
  grid-area:copy!important;grid-column:1!important;grid-row:1!important;align-self:center!important}
 .tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy strong{font-size:clamp(15px,4.2vw,19px)!important;
  line-height:1.15!important;-webkit-line-clamp:3!important}
 .tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy p{font-size:11px!important;line-height:1.3!important}
 .tcStitchShell .tcInlineHousePromo>button{
  grid-area:cta!important;grid-column:1!important;grid-row:2!important;
  justify-self:stretch!important;min-height:38px!important}
 .tcStitchShell .tcInlineHousePromo .tcInlineGalleryControls button,
 .tcStitchShell .tcHouseAd.tcPremiumAd .tcHouseGalleryControls button{
  flex-basis:17px!important;width:17px!important;min-width:17px!important;
  height:22px!important;min-height:22px!important}
 .tcStitchShell .tcStitchAdvertising .tcHouseAd.tcPremiumAd{
  grid-template-columns:minmax(0,1fr) minmax(125px,.78fr)!important}
}
@media(prefers-reduced-motion:reduce){
 .tcStitchShell .tcInlineGalleryControls button::after,
 .tcStitchShell .tcHouseGalleryControls button::after{transition:none!important}
}

import {HOUSE_DEFAULTS,type Creative} from '../shared/house-ads';
const legacy:Record<string,Pick<Creative,'title'|'message'|'mobileMessage'|'button'>>={
  "house-professionals": {
    "title": "¿Tienes un oficio o profesión?",
    "message": "¿Tienes un oficio o profesión? Ofrece tus servicios gratis en Trabajo Cerca.",
    "mobileMessage": "Ofrece tu oficio o profesión gratis.",
    "button": "Publicar mis servicios"
  },
  "house-advertisers": {
    "title": "Tu negocio, más cerca de tus clientes.",
    "message": "Promociona tu negocio en Trabajo Cerca y aprovecha nuestra publicidad gratuita de lanzamiento.",
    "mobileMessage": "Conoce nuestra promoción de lanzamiento.",
    "button": "Publicitar mi negocio"
  },
  "house-employers": {
    "title": "¿Necesitas alguien para trabajar?",
    "message": "¿Necesitas contratar trabajadores o servicios? Publica tu oportunidad en Trabajo Cerca.",
    "mobileMessage": "¿Necesitas contratar? Publica aquí.",
    "button": "Publicar una necesidad"
  },
  "house-explore": {
    "title": "Trabajo Cerca nace para nuestras comunas.",
    "message": "Trabajo, servicios y negocios cerca de ti. Descubre Trabajo Cerca.",
    "mobileMessage": "Trabajo y servicios cerca de ti.",
    "button": "Conocer Trabajo Cerca"
  },
  "house-inclusion": {
    "title": "Aquí hay espacio para todos.",
    "message": "Desde el trabajo agrícola hasta los servicios técnicos y profesionales. Si sabes hacer algo, puedes ofrecerlo.",
    "mobileMessage": "Todos los oficios tienen espacio aquí.",
    "button": "Ofrecer mis servicios"
  },
  "house-local-business": {
    "title": "¿Ofreces alojamiento, alimentación o servicios para empresas?",
    "message": "Da a conocer tus servicios a personas, trabajadores y empresas de nuestro territorio.",
    "mobileMessage": "Alojamiento, alimentación y servicios locales.",
    "button": "Promocionar mi negocio"
  }
};
const lastPresentation={"house-professionals": {"title": "¿Buscas trabajo? Hazte visible.", "message": "Publica gratis lo que sabes hacer y desde cuándo estás disponible.", "mobileMessage": "Publica gratis lo que sabes hacer y tu disponibilidad.", "button": "Ofrecer mi trabajo"}, "house-advertisers": {"title": "Tu negocio puede destacar aquí.", "message": "Promociona tus productos o servicios cerca de tus clientes.", "mobileMessage": "Promociona tu negocio cerca de tus clientes.", "button": "Publicitar mi negocio"}, "house-employers": {"title": "¿Necesitas alguien para trabajar?", "message": "Encuentra personas disponibles o publica lo que necesitas.", "mobileMessage": "Encuentra personas o publica lo que necesitas.", "button": "Necesito contratar"}, "house-explore": {"title": "Oportunidades cerca de ti.", "message": "Descubre empleos, personas y servicios de tu territorio.", "mobileMessage": "Empleos, personas y servicios de tu territorio.", "button": "Explorar oportunidades"}, "house-inclusion": {"title": "Lo que sabes hacer tiene valor.", "message": "Agricultura, construcción, oficios, servicios técnicos y profesiones. Todos tienen espacio aquí.", "mobileMessage": "Oficios, servicios y profesiones. Todos tienen espacio aquí.", "button": "Publicar mis servicios"}, "house-local-business": {"title": "Que conozcan tu negocio local.", "message": "Alojamiento, alimentación, transporte y servicios para trabajadores y empresas.", "mobileMessage": "Alojamiento, alimentación, transporte y servicios locales.", "button": "Promocionar mi negocio"}};
// Previous built-in text is upgraded in the UI without modifying a campaign
// that an administrator has customized. The current saved campaigns are unchanged.
const previousDefaults:Record<string,Pick<Creative,'title'|'message'|'mobileMessage'|'button'>>={
  'house-professionals':{title:'¿Buscas trabajo?',message:'Muestra lo que sabes hacer. Gratis.',mobileMessage:'Muestra lo que sabes hacer. Gratis.',button:'Publicar mi perfil'},
  'house-advertisers':{title:'Haz que conozcan tu negocio.',message:'Promociónate entre clientes de tu zona.',mobileMessage:'Promociónate entre clientes de tu zona.',button:'Conocer promoción'},
  'house-employers':{title:'¿Necesitas contratar?',message:'Publica lo que necesitas y conecta con personas de tu zona.',mobileMessage:'Conecta con personas de tu zona.',button:'Publicar necesidad'},
  'house-explore':{title:'Oportunidades cerca de ti.',message:'Empleos, personas y servicios de tu territorio.',mobileMessage:'Empleos, personas y servicios de tu zona.',button:'Explorar oportunidades'},
  'house-inclusion':{title:'Lo que sabes hacer vale.',message:'Oficios y profesiones: ofrece tus servicios gratis.',mobileMessage:'Ofrece tus servicios gratis.',button:'Ofrecer mis servicios'},
  'house-local-business':{title:'Servicios para empresas.',message:'Alojamiento, alimentación y transporte cerca de quienes trabajan.',mobileMessage:'Alojamiento, alimentación y transporte.',button:'Promocionar mi negocio'},
};
// Upgrade untouched defaults only. Administrator edits and image withdrawals win.
export function presentHouseCreative(campaignId:string,creative:Creative):Creative {
 const defaults=HOUSE_DEFAULTS.find(c=>c.id===campaignId)?.creatives.find(c=>c.id===creative.id);
 const previous=legacy[campaignId];const recent=(lastPresentation as Record<string,typeof previous>)[campaignId];
 const unchanged=previousDefaults[campaignId];
 const untouched=[previous,recent,unchanged].some(old=>old&&(['title','message','mobileMessage','button'] as const).every(key=>creative[key]===old[key]));
 const text=untouched&&defaults?{...creative,title:defaults.title,message:defaults.message,mobileMessage:defaults.mobileMessage,button:defaults.button}:creative;
 const priorDefault=creative.imageUrl==='/house-creatives/'+campaignId.replace('house-','')+'.svg';
 return {...text,...(!creative.imageDisabled&&!creative.storagePath&&(!creative.imageUrl||priorDefault)&&defaults?.imageUrl?{imageUrl:defaults.imageUrl}:{}),...(creative.imageDisabled?{imageUrl:undefined}:{})};
}

import {safeAdImage} from '../shared/ad-images';

/**
 * Institutional carousel media: prefer the administrator-approved creative on
 * the campaign's first slide; use the matching original institutional photo
 * on secondary slides. Disabled means disabled across the entire carousel.
 *
 * Fail closed for arbitrary URLs. <AdImage> handles image load failures and
 * exposes the existing SVG underneath rather than rendering a broken card.
 */
export function selectHousePhotoUrl(input:{
  imageDisabled?:boolean;
  customUrl?:string;
  defaultUrl?:string;
  firstSlide:boolean;
}):string|undefined {
  if(input.imageDisabled===true) return undefined;
  const custom=input.firstSlide?safeAdImage(input.customUrl):undefined;
  return custom??safeAdImage(input.defaultUrl);
}

import type {Goal} from '../shared/house-ads';
export const ARTWORK=['explore','professionals','inclusion','local-business','advertisers','employers'] as const;
export type Art=typeof ARTWORK[number];
export const STORIES:Record<Art,{eyebrow:string;title:string;message:string;mobile:string;cta:string;goal:Goal}>={
 explore:{eyebrow:'TRABAJO CERCA · 12 COMUNAS',title:'Lo que buscas puede estar cerca.',message:'Empleos, oficios y negocios locales de nuestras 12 comunas.',mobile:'Encuentra oportunidades de tu territorio.',cta:'Explorar mi territorio',goal:'explore'},
 professionals:{eyebrow:'PERSONAS Y EXPERIENCIA',title:'Haz visible tu experiencia.',message:'Ofrece tus habilidades y disponibilidad con contacto directo.',mobile:'Comparte tus habilidades y disponibilidad.',cta:'Publicar mi perfil',goal:'professional'},
 inclusion:{eyebrow:'OFICIOS Y SERVICIOS',title:'Muestra lo que sabes hacer.',message:'Reparaciones, soldadura, gastronomía y otros oficios de tu comuna.',mobile:'Que conozcan tus oficios y servicios locales.',cta:'Publicar mi servicio',goal:'professional'},
 'local-business':{eyebrow:'NEGOCIOS LOCALES',title:'Que elijan tu negocio local.',message:'Da a conocer tu comercio, productos y atención a tus vecinos.',mobile:'Tu negocio merece ser visto en la comuna.',cta:'Promocionar mi negocio',goal:'advertiser'},
 advertisers:{eyebrow:'PUBLICIDAD PARA EMPRENDEDORES',title:'Tu anuncio puede contar más.',message:'Muestra productos, horarios, servicios y contacto en publicidad local.',mobile:'Presenta horarios, productos y contacto.',cta:'Anunciar mi negocio',goal:'advertiser'},
 employers:{eyebrow:'PERSONAS Y EMPLEADORES',title:'¿Necesitas contratar?',message:'Publica lo que necesitas y conecta con personas de la zona.',mobile:'Encuentra personas disponibles cerca de ti.',cta:'Publicar necesidad',goal:'employer'}
};
export function houseSequence(id:string):Art[]{
 const raw=id.replace(/^house-/,'');
 const first=ARTWORK.includes(raw as Art)?raw as Art:'explore';
 return [first,...ARTWORK.filter(a=>a!==first)];
}

@tailwind base;
.tcBootShell{min-height:65vh;background:#f8faf8;color:#133b2a;padding:22px;font-family:system-ui,sans-serif}
.tcBootShell>strong{font-size:18px}.tcBootShell p{font-size:13px;margin:20px 0;background:#eaf3eb;padding:14px;border-radius:12px}
.tcBootShell>div{height:86px;background:#fff;border:1px solid #dce9dd;border-radius:12px;margin:10px 0}

@tailwind components;
@tailwind utilities;

:root{
  font-family:'Plus Jakarta Sans',ui-sans-serif,system-ui,-apple-system,sans-serif;
  color:#1a201c;background:#faf9f5;font-synthesis:none;
  --forest:#1e3d30;--forest-deep:#0d281e;--sage:#587b6d;--terracotta:#c46243;
  --ivory:#faf9f5;--white:#fff;--sand:#efece6;--line:#e3dfd5;--text:#1a201c;--muted:#667069;
}
*{box-sizing:border-box}html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;text-size-adjust:100%}body{margin:0;background:var(--ivory);color:var(--text)}
button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.45}
.appShell{min-height:100vh;padding-bottom:0}.topbar{height:68px;padding:0 max(20px,calc((100% - 1180px)/2));display:flex;align-items:center;justify-content:space-between;gap:20px;background:#faf9f5e8;backdrop-filter:blur(18px);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:40}
.brand{display:flex;align-items:center;gap:10px}.brandButton{border:0;background:transparent;padding:0;text-align:left}.brand>div:last-child{display:flex;flex-direction:column}.brand b{font-size:18px;color:var(--forest-deep);letter-spacing:-.02em}.brand span{font-size:8px;letter-spacing:.13em;font-weight:700;color:#758078;margin-top:2px}
.brandmark{width:40px;height:40px;border:1px solid var(--line);border-radius:12px;background:white;color:var(--forest);display:grid;place-items:center;position:relative}.brandmark svg:last-child:not(:first-child){position:absolute;right:3px;bottom:3px;background:var(--ivory);border-radius:50%;padding:1px;width:14px}
.topbarActions{display:flex;align-items:center;gap:10px}.communePicker{height:38px;border:1px solid var(--line);background:white;border-radius:999px;padding:0 10px;display:flex;align-items:center;gap:4px;color:var(--terracotta)}.communePicker select{border:0;outline:0;background:transparent;color:var(--forest);font-size:11px;font-weight:600;max-width:150px}.radarLive{display:flex;align-items:center;gap:6px;font-size:10px;color:#5f6c65;font-weight:600}.radarLive>span{width:7px;height:7px;border-radius:50%;background:#5a8b68;box-shadow:0 0 0 4px #5a8b6814}

.homeHero{max-width:1180px;margin:0 auto;padding:68px 20px 34px;display:grid;grid-template-columns:1.35fr .65fr;gap:42px;align-items:end}.homeCopy{max-width:760px}.overline{font-size:9px;letter-spacing:.13em;font-weight:700;color:var(--terracotta)}.homeHero h1{font-size:clamp(44px,6.5vw,78px);line-height:.98;letter-spacing:-.055em;margin:10px 0 16px;color:var(--forest-deep);font-weight:700}.mobileBreak{display:none}.homeHero p{font-size:16px;line-height:1.6;color:#626c66;max-width:650px;margin:0 0 24px}.heroSearch{height:58px;background:white;border:1px solid var(--line);border-radius:15px;display:flex;align-items:center;gap:10px;padding:0 15px;color:#8b948e;max-width:720px}.heroSearch input{border:0;outline:0;background:transparent;flex:1;font-size:14px;color:var(--text)}.heroSearch button{border:0;background:transparent;color:#8b948e;display:grid;place-items:center}.quickChips{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.quickChips button{border:1px solid var(--line);background:white;color:#5a645e;border-radius:999px;padding:7px 11px;font-size:10px;font-weight:500}
.heroSummary{background:white;border:1px solid var(--line);border-radius:18px;padding:22px;min-height:245px;display:flex;flex-direction:column;justify-content:flex-end}.heroSummaryTop{display:flex;align-items:center;gap:8px;color:var(--sage);font-size:9px;font-weight:700;letter-spacing:.08em;margin-bottom:auto}.pulseIcon{width:34px;height:34px;border-radius:12px;background:#f2f4f0;display:grid;place-items:center;color:var(--forest)}.pulseIcon svg{width:18px}.heroSummary strong{font-size:46px;line-height:1;color:var(--forest);letter-spacing:-.04em}.heroSummary>b{font-size:13px;color:#39463f;margin-top:4px}.heroSummary p{font-size:10px;margin:7px 0 15px;color:#78827b}.heroSummary button{border:0;background:var(--terracotta);color:white;border-radius:11px;padding:12px 13px;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:space-between}.heroSummary button svg{width:15px}

